import itertools

def lexicographically_smallest_s(s):
    for K in range(1, len(s)):
        subsequences = list(itertools.combinations(range(len(s)), K))
        for seq in subsequences:
            if seq != ():
                candidate = ''.join(s[i] for i in seq)
                for index in range(K - len(seq)) + range(K, len(s)):
                    if not (index < K and candidate.startswith(s[index])):
                        candidate = candidate[-1] + candidate[:-1]
                        break
                if candidate < s:
                    return candidate
    candidates = sorted([candidate for seq in subsequences for candidate in itertools.product(*([s[i] for i in seq]])], key=lambda x: "".join(x))
