                    next_val = val + (i == 0 - dp[i - 1][val])
                    if -1 < next_val <= k:
                        dp[i][next_val] += dp[i - 1][val]
                        dp[i][next_val] %= 1000000007
                    next_val = val - (i == 0 - dp[i - 1][val])
                    if -1 < next_val <= k:
                        cur_dp[i][next_val] += dp[i - 1][val]
                        cur_dp[i][next_val] %= 1000000007
