def query_t3(n, q, a, w, v, queries):
    dp = [[0 for _ in range(n + 1)] for _ in range(q + 1)]

    for day in range(1, q + 1):
        for i in range(n):
            dp[day][i] = dp[day - 1][i]
            for j in range(a[i], 0, -1):
                dp[day][i] += dp[day - 1][j - 1]

        for query in queries[day]:
            expected_value, expected_weight = query
            index = expected_weight - 1

            for trade_type in range(expected_weight, 0, -1):
                while index >= 0 and (dp[day - 1][index] == dp[day][index] or w * (index + 1) * index // 2 > v * (j + 1) * j // 2) and trade_type + j <= expected_weight:
                    index -= 1
                    j += 1

                current_value = dp[day - 1][index]

                ratio = j / (j + 1)

                if current_value == dp[day][index]:
                    break

                bias = (expected_value - v * j) / v

                dp[day][index] -= minimum_cost_index(bias, a[i], expected_weight, ratio)

    return dp[q][n-1]

def minimum_cost_index(bias, a, expected_weight, ratio):
    lb, ub = 0, max(2 * a, (2 * a ** 2 - 8 * bias) ** 0.5 + expected_weight + 1)

    while lb + 1 < ub:
        mid = (lb + ub) // 2
        actual_weight = ratio * (mid ** 2 + 4 * mid + 8 * bias) // 8

        if actual_weight > expected_weight:
            ub = mid
        else:
            lb = mid

    smallest = ub
    closest = ub
    for candidate in range(1, smallest, closest):
        actual_weight = ratio * (candidate ** 2 + 4 * candidate + 8 * bias) // 8
        if actual_weight > expected_weight:
            break
        if (candidate - smallest) < (smallest - closest):
            smallest = candidate
            closest = smallest

    return smallest
