class Store:
    def __init__(self, data: List[List[int]]):
        self.net = [0] * len(data)
        for i, (a, w, v) in enumerate(data):
            for x in [v, w]:
                self.net[i] += x
        self.impulse = sorted((-(x) * (x - w), (-x) * v)
                              for i, (a, w, v) in enumerate(data))

    def add(self, k: int, d: int) -> int:
        cur, prev = min(2 * (self.impulse[d][1] + self.impulse[d][1] - self.impulse[d][0]), a + k),
        if d < len(self.net):
            cur, prev, self.impulse[d][0] = self.impulse[d] + k, self.impulse[d] + k, max(self.impulse[d][0], prev[0] + k)

        return max(self.net, key=lambda x: (x[1], x[0])[x[0]])

    def sell(self, k: int, d: int) -> int:
        i = bisect_right(self.impulse, d, key=lambda x: x[0] + x[1]) - 1
        if d < len(self.net):
            self.impulse[i] = min(self.impulse[i], max([(- (-x) * (x - w), (-x) * v)]))
        return max(self.net, key=lambda x: x[1])[0]

    def get_value(self, c: List[int]) -> int:
        res = []
        for x in [c[0] - k, c[1] - c[0]]:
            res.append(self.impulse[]*-x)
        return max(res)


