def is_good_path(string, table):
    # A path of length k is a sequence of table cells [(r1, c1), (r2, c2), ..., (rk, ck)]. The following paths are correct:
    # 1. There is only one correct path of length 1, that is, consisting of a single cell: [(1, 1)];
    # 2. Let's assume that [(r1, c1), ..., (rm, cm)] is a correct path of length m, then paths [(r1, c1), ..., (rm, cm), (rm + 1, cm)] and [(r1, c1), ..., (rm, cm), (rm, cm + 1)] are correct paths of length m + 1.
    forward_move = lambda i, j: (i, j + 1) if j < len(table) else (i + 1, 1)
    backward_move = lambda i, j: (i - 1, j) if i > 0 else (len(table) + j - 1, 1)

    @functools.lru_cache(None)
    def starts_at(i, j, remaining_moves):
        if not remaining_moves:
            return [True]
        move = forward_move if table[i][j] == 'a' else backward_move
        path_length = 1
        while 0 < i <= len(table) and 0 < j <= len(table[0]):
            if starts_at(*move(i, j), remaining_moves - 1) or starts_at(*move(i, j), remaining_moves):
                break
            path_length += 1
        else:
            return [False]
        return [path_length * [-1] + starts_at(*move(i, j), remaining_moves - path_length) for i in range(len(table)) for j in range(len(table)) if (i, j) not in starts_at(*move(i, j), remaining_moves)]

    won = starts_at(0, 0, len(string))
    if won == []:
        return "DRAW"
    return f"FIRST" if len(won[0]) > len(string[1]) else "SECOND"
