import bisect

def solve(N, Q, A, queries):
    result = []
    for query in queries:
        if query[0] == 1:
            index, value = query[1] - 1, query[2]
            A[index] = value
        elif query[0] == 2:
            left, right = query[1] - 1, query[2] - 1
            if not can_sort(A, left, right):
                result.append("-1")
            else:
                closest = find_closest(A, left, right)
                result.append(str(closest))
    return "\n".join(result)

def can_sort(a, left, right):
    if right - left + 1 < 3:
        return True
    sorted_part = a[left:right+1]
    if sorted_part:
        return sorted(sorted_part) == sorted_part

def find_closest(a, left, right):
    left_index, right_index = bisect.bisect_left(a, -1), bisect.bisect_right(a, -1)
    left_count, right_count = right_index - left_index, len(a) - 1 - right_index
    count_to_adjust = left_count - right_count
    results = []
    for value in range(-(left_count), left_count + 1):
        found_left = a[left_index] - count_to_adjust - value
        found_right = a[right_index] + count_to_adjust - value
        if found_left >= 0 and is_possible_to_span(found_left, a, left, right) or found_right >= 0 and is_possible_to_span(found_right, a, left, right):
            results.append(value)
    return min(results) if results else -1

def is_possible_to_span(start_value, sorted_a, left, right):
    start_index = bisect.bisect_right(sorted_a, start_value)
    current_value = start_value
    while start_index < len(sorted_a) and start_index < right:
        current_value += sorted_a[start_index]
        start_index += 1
        if start_index <= left or current_value > start_value + 2:
            return False
    return True

