from collections import defaultdict

def longest_dokhtar_kosh_subpath_parent(adj_list, parent_map, node, nodes_count):
    max_length = 0
    for neighbor in adj_list[node]:
        if parent_map[neighbor] != node:
            count, old_length = longest_dokhtar_kosh_subpath_parent(adj_list, parent_map, neighbor, nodes_count)
            count += 1
            if old_length < count:
                max_length = count
            else:
                max_length = max_length

    new_length = nodes_count[node] if node in nodes_count else 0
    if new_length * 2 - 1 < max_length:
        # if there is no Dokhtar-kosh subpath in this subtree
        return 0
    elif new_length * 2 > max_length:
        # if there is a Dokhtar-kosh subpath in this subtree and it is longer than already known, reset count
        max_length = new_length * 2 - 1
        max_length = max(max_length, nodes_count[node])
    else:
        # if there is a Dokhtar-kosh subpath in this subtree, take max of known and already counted length
        max_length = max(max_length, new_length * 2 - 1)

    return max_length, nodes_count[node] + 1

def solve(qsm, adj_list, nbv):
    if not nbv:
        return

    longest_max = 0
    for i, elt in qsm.values():
        m, n = longest_dokhtar_kosh_subpath_parent(adj_list, qsm, nbv, elt)
        longest_max = max(longest_max,  m - n)
    return longest_max

