    return (dp[:y+2] * inverse(dp[y] * (x+1)) * inverse((x+1)**(y-1))).sum() % mod


def full_sum(dp, y):
    sum = 0
    for x in range(y+1):
        sum = (sum + dp[x]) % mod
    return sum
